namespace ghidra.app.extension.datatype.finder;



using docking.widgets.search;
using ghidra.app.decompiler;
using ghidra.app.services;
using ghidra.app.services;
using ghidra.program.model.address;
using ghidra.program.model.data;
using ghidra.program.model.listing;
using ghidra.util.exception;

/**
 * Represents a type declaration and variable pair.
 */
public abstract class VariableDR : DecompilerReference {

	protected DecompilerVariable declaration;

	protected VariableDR(ClangLine line, ClangTypeToken type) : base(line, type)
    {

		declaration = new DecompilerVariableType(type);
	}

	void setVariable(ClangVariableToken token) {
		variable = new DecompilerVariableType(token);
	}

	public DecompilerVariable getDeclaration() {
		return declaration;
	}

	/* @Override */
	public DecompilerVariable getVariable() {
		return variable;
	}

	/* @Override */
	public void accumulateMatches(DataType dt, FieldMatcher fieldMatcher,
			List<DataTypeReference> results) {

		if (variable == null) {
			// This implies our API was misused in that a variable was never set after creation
			throw new AssertException("Decompiler variable declaration is missing a name");
		}

		DataType dataType = getDataType();
		if (!isEqual(dataType, dt)) {
			return; // wrong type, nothing to do
		}

		string name = variable.getName();
		int offset = variable.getOffset();
		if (fieldMatcher.matches(name, offset)) {

			// this will be null if the field matcher is empty
			string fieldName = fieldMatcher.getFieldName();
			Function function = getFunction();
			Address address = getAddress();
			SearchLocationContext context = getContext();
			results.add(new DataTypeReference(dataType, fieldName, function, address, context));
		}
	}

}
